package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
/** Private user-created places. Images are bounded JPEGs inside authenticated encryption. */
public final class NavigationLandmarks {
 static final String STORE="navigation-landmarks";
 public static synchronized JSONArray list(Context c)throws Exception{android.util.AtomicFile f=ConversationWorkspace.file(c,STORE);if(!f.getBaseFile().exists()&&!new File(f.getBaseFile()+".bak").exists())return new JSONArray();return ConversationWorkspace.read(c,STORE).getJSONArray("items");}
 public static JSONObject safe(JSONObject in)throws Exception{String id=in.optString("id"),name=in.optString("name").trim(),note=in.optString("note");if(!id.matches("[a-f0-9-]{36}")||name.isEmpty()||name.length()>80||note.length()>600)throw new IOException("名前・メモを確認してください");JSONObject out=new JSONObject().put("id",id).put("revision",in.optInt("revision")).put("name",name).put("note",note);if(in.has("latitude")||in.has("longitude")){JSONObject point=new JSONObject(in.toString()).put("name",name);if(!SavedNavigationRoutes.located(point))throw new IOException("地点を選び直してください");out.put("latitude",in.getDouble("latitude")).put("longitude",in.getDouble("longitude"));}String photo=in.optString("photo");if(!photo.isEmpty()){if(photo.length()>350000)throw new IOException("写真が大きすぎます");byte[] bytes=android.util.Base64.decode(photo,android.util.Base64.NO_WRAP);if(bytes.length>256000||bytes.length<4||(bytes[0]&255)!=255||(bytes[1]&255)!=216)throw new IOException("写真の形式を確認してください");out.put("photo",photo);}return out;}
 public static synchronized JSONObject save(Context c,JSONObject in)throws Exception{JSONObject row=safe(in);JSONArray rows=list(c),next=new JSONArray();boolean found=false;for(int i=0;i<rows.length();i++){JSONObject old=rows.getJSONObject(i);if(old.getString("id").equals(row.getString("id"))){if(old.optInt("revision")!=row.optInt("revision"))throw new IOException("記録が更新されています。開き直してください");found=true;}else next.put(old);}if(!found&&row.optInt("revision")!=0)throw new IOException("削除された記録です");if(next.length()>=12)throw new IOException("保存は12件までです");row.put("revision",row.optInt("revision")+1);next.put(row);ConversationWorkspace.write(c,STORE,new JSONObject().put("items",next));return row;}
 public static synchronized void remove(Context c,String id,int revision)throws Exception{JSONArray rows=list(c),next=new JSONArray();boolean found=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))){if(row.optInt("revision")!=revision)throw new IOException("記録が更新されています");found=true;}else next.put(row);}if(!found)throw new IOException("削除済みです");ConversationWorkspace.write(c,STORE,new JSONObject().put("items",next));}
 public static JSONArray summaries(Context c)throws Exception{JSONArray out=new JSONArray(),rows=list(c);for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);out.put(new JSONObject().put("name",p.getString("name")).put("note",p.optString("note")).put("hasPhoto",!p.optString("photo").isEmpty()));}return out;}
 public static JSONObject linked(Context c,String id)throws Exception{if(id==null||id.isEmpty())return null;JSONArray rows=list(c);for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).optString("id")))return new JSONObject(rows.getJSONObject(i).toString());throw new IOException("関連付けたメモは削除されています");}
 private NavigationLandmarks(){}
}
